/* Original calendar UI. Availability is never inferred from the date grid. */
(function(root){
  function daysInMonth(year,month){return new Date(Date.UTC(year,month+1,0)).getUTCDate();}
  function monthCells(year,month){const offset=(new Date(Date.UTC(year,month,1)).getUTCDay()+6)%7;return [...Array(offset).fill(null),...Array.from({length:daysInMonth(year,month)},(_,i)=>i+1)];}
  function localToday(timezone,now=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`;}
  function dateKey(year,month,day){return `${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;}
  function safeBookingUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u:null;}catch{return null;}}
  const api={daysInMonth,monthCells,localToday,dateKey,safeBookingUrl};
  if(typeof module!=='undefined'&&module.exports){module.exports=api;return;}
  const config=root.SUNFLOWER_CONFIG, mount=document.getElementById('calendar-mount'),today=localToday(config.timezone),[year,month]=today.split('-').map(Number);let view=new Date(Date.UTC(year,month-1,1)),selected=null;
  const contact=config.contactEnabled===true&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(config.contactEmail);
  const provider=safeBookingUrl(config.bookingUrl),live=config.bookingEnabled===true&&!!provider;
  const fmt=new Intl.DateTimeFormat('en-IN',{month:'long',year:'numeric',timeZone:'UTC'});
  const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e;};
  function dateLabel(key){return new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(key+'T12:00:00Z'));}
  function enquiryLink(key){const subject='Appointment enquiry'+(key?' — '+dateLabel(key):'');const body=`Hello Nayana,\n\nI would like to enquire about a session${key?' on '+dateLabel(key):''}.\nPreferred time (India Standard Time): \nPreferred session length: 60 minutes\n\nPlease let me know your availability and session fee.\n\nThank you.`;return `mailto:${config.contactEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;}
  function showProvider(container){
    const notice=el('p','embed-disclosure','The secure calendar is provided by Cal.com. Opening it connects to Cal.com and its privacy terms apply.');const button=el('button','button','Open secure calendar ↗');container.append(notice,button);
    button.addEventListener('click',()=>{button.remove();if(config.embedEnabled&&['cal.com','www.cal.com'].includes(provider.hostname)){
      const u=new URL(provider);u.searchParams.set('embed','true');u.searchParams.set('theme','light');const frame=el('iframe','booking-frame');frame.title='Book an appointment with Nayana Binuraj Antony';frame.src=u.href;frame.referrerPolicy='strict-origin-when-cross-origin';container.append(frame);
    }else{window.open(provider.href,'_blank','noopener,noreferrer');}const fallback=el('a','text-link','Open calendar in a new tab ↗');fallback.href=provider.href;fallback.target='_blank';fallback.rel='noopener noreferrer';container.append(fallback);});
  }
  function render(){
    mount.replaceChildren();const heading=el('div','calendar-brand');const logo=el('img','calendar-logo');logo.src='assets/sunflower-mind-logo.webp';logo.alt='Sunflower Mind';logo.width=57;logo.height=61;const label=el('div');label.append(el('p','calendar-kicker','YOUR APPOINTMENT'),el('h3','',config.practitionerName));if(config.professionalTitle)label.append(el('p','calendar-profession',config.professionalTitle));if(config.qualifications)label.append(el('p','calendar-qualifications',config.qualifications));heading.append(logo,label);mount.append(heading);
    if(live){showProvider(mount);return;}
    mount.append(el('p','calendar-mode',contact?'Enquire about a date':'Your appointment calendar'),el('p','calendar-explainer',contact?'Choose a preferred date to include in your email. Dates shown are not confirmed availability.':'Explore dates while we prepare online booking. Dates shown are not confirmed availability.'));
    const bar=el('div','calendar-toolbar'),prev=el('button','calendar-arrow','←'),next=el('button','calendar-arrow','→'),caption=el('h4','',fmt.format(view));caption.setAttribute('aria-live','polite');prev.setAttribute('aria-label','Previous month');next.setAttribute('aria-label','Next month');const delta=(view.getUTCFullYear()-year)*12+view.getUTCMonth()-(month-1);prev.disabled=delta<=0;next.disabled=delta>=11;prev.onclick=()=>{view.setUTCMonth(view.getUTCMonth()-1);render();mount.querySelector('.calendar-arrow').focus()};next.onclick=()=>{view.setUTCMonth(view.getUTCMonth()+1);render();mount.querySelectorAll('.calendar-arrow')[1].focus()};bar.append(prev,caption,next);mount.append(bar);
    const weekdays=el('div','calendar-weekdays');['M','T','W','T','F','S','S'].forEach((d,i)=>{const span=el('span','',d);span.setAttribute('aria-label',['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]);weekdays.append(span)});mount.append(weekdays);
    const grid=el('div','calendar-days');grid.setAttribute('role','group');grid.setAttribute('aria-label','Choose a preferred date for an enquiry');monthCells(view.getUTCFullYear(),view.getUTCMonth()).forEach(day=>{if(day===null){grid.append(el('span'));return;}const key=dateKey(view.getUTCFullYear(),view.getUTCMonth(),day),b=el('button',key===selected?'selected':'',String(day));b.disabled=key<today;b.type='button';b.setAttribute('aria-label',dateLabel(key)+' — enquire, availability unconfirmed');b.setAttribute('aria-pressed',String(key===selected));if(key===today)b.setAttribute('aria-current','date');b.onclick=()=>{selected=key;render();mount.querySelector('[aria-pressed="true"]').focus()};grid.append(b)});mount.append(grid);
    const selection=el('p','calendar-selection',selected?'Preferred date: '+dateLabel(selected):'Select a date, or ask for a time that suits you.');selection.setAttribute('aria-live','polite');mount.append(selection);const action=el(contact?'a':'button','button calendar-enquire',contact?'Enquire by email ↗':'Online booking opens soon');if(contact)action.href=enquiryLink(selected);else action.disabled=true;mount.append(action,el('p','calendar-footnote',contact?'No slot is reserved. Nayana will confirm the time and fee. Online booking is awaiting account activation.':'No appointment is reserved. Your selection is not saved or sent. Confirmed times and fees will appear when booking opens.'));
  }
  root.openSunflowerBooking=function(){const d=document.getElementById('booking'),content=document.getElementById('booking-content');content.replaceChildren();if(live){showProvider(content);}else{content.append(el('p','status',contact?'Appointment enquiries are open':'Online appointments opening soon'),el('p','',`Sessions typically last ${config.sessionMinutes} minutes. You can request a different duration or a time that works for you. Online booking confirmation is not active yet.`));if(selected)content.append(el('p','',`Preferred date: ${dateLabel(selected)} · India Standard Time`));const email=el('a','button','Email Nayana ↗');email.href=enquiryLink(selected);const calendar=el('button','text-link','Choose a preferred date ↓');calendar.onclick=()=>{d.close();document.getElementById('appointments').scrollIntoView({behavior:root.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});};if(contact)content.append(email);content.append(calendar,el('p','contact-caution',contact?'An enquiry is not a confirmed booking. Please avoid sending sensitive health information by email.':'No booking or payment is made here. Practice contact details will be published when enquiries open.'));}d.showModal();};
  render();
})(typeof window!=='undefined'?window:globalThis);
